# -*- coding: utf-8 -*-
"""0.6.0 批次风格定义：Aix0111–Aix0160（对应收藏图 101–150）。

定义原则：保留收藏图的视觉语法，不把原图主体当作不可迁移的唯一题材；
核心特征均描述媒介、色彩、构图和边缘关系，样例计划再将语法迁移到人物、物体、场景。
"""


def features(*rows):
    return [{"id": "F%02d" % (i + 1), "axis": axis, "tier": tier, "text": text}
            for i, (axis, tier, text) in enumerate(rows)]


def avoid(*texts):
    return [{"id": "N%02d" % (i + 1), "text": text} for i, text in enumerate(texts)]


def make_plan(motif, conflict, obj1, obj2, setting, anchors):
    a, b = anchors
    return [
        ("人物", "在%s中，一个人物以清晰轮廓面对%s，保持%s，表现%s。" % (setting, motif, a, conflict), [a, b]),
        ("人物", "侧身或背影人物与%s形成强烈的方向或尺度关系，留出负空间，延续%s。" % (motif, b), [a, b]),
        ("物体", "%s被%s重新组织成异常视觉核心，背景保持简洁并表达%s。" % (obj1, motif, conflict), [a, b]),
        ("物体", "%s作为孤立日常物件置于%s的构图中，使用%s制造隐喻。" % (obj2, setting, motif), [a, b]),
        ("场景", "远景以%s作为主结构，采用%s的构图秩序，把%s转译成环境叙事。" % (motif, a, conflict), [a, b]),
        ("场景", "一个%s场景保留%s与%s的视觉张力，避免文字和多余装饰。" % (setting, motif, b), [a, b]),
    ]


def style(row):
    return {
        "id": row["id"], "name": row["name"], "category": row["category"],
        "description": row["description"], "tags": row["tags"],
        "aliases": row["aliases"], "alt": row["alt"],
        "features": features(
            ("medium", "core", row["medium"]),
            ("palette", "core", row["palette"]),
            ("composition", "core", row["composition"]),
            ("lighting", "support", row["lighting"]),
            ("texture", "support", row["texture"]),
        ),
        "avoid": avoid(*row["avoid"]), "suitable_for": row["suitable"],
        "weak_for": row["weak"], "known_failures": [row["failure"]],
        "plan": make_plan(row["motif"], row["conflict"], row["obj1"], row["obj2"], row["setting"], row["anchors"]),
    }


R = lambda id, name, category, description, tags, aliases, alt, medium, palette, composition, lighting, texture, avoid_rows, suitable, weak, failure, motif, conflict, obj1, obj2, setting, anchors: {
    "id": id, "name": name, "category": category, "description": description,
    "tags": tags, "aliases": aliases, "alt": alt, "medium": medium,
    "palette": palette, "composition": composition, "lighting": lighting,
    "texture": texture, "avoid": avoid_rows, "suitable": suitable, "weak": weak,
    "failure": failure, "motif": motif, "conflict": conflict, "obj1": obj1,
    "obj2": obj2, "setting": setting, "anchors": anchors,
}


