R("Aix0123", "黑洞捧持", "graphic", "人物双手捧住黑色圆洞，头部被黑矩形遮挡，同心圆把拥抱虚无和隐藏身份变成克制的单色海报。", ["黑洞", "同心圆", "隐藏身份", "灰黑白", "极简海报"], ["黑洞捧持", "held void", "monochrome portal"], "以捧持动作、黑色圆洞和同心圆构图表现拥抱虚无的极简概念海报。", "极简平涂与轻颗粒结合，几何边缘必须干净。", "灰、黑、白三色分层，中心黑洞拥有最高对比。", "双手围绕圆形核心，头部遮挡形成第二个矩形负形。", "均匀平光，依靠圆形层级与黑白关系塑造空间。", "细微纸面颗粒和套印感，不加入写实材质。", ["复杂多色背景", "写实人物表情", "乱码文字与伪文字"], ["哲思海报", "品牌概念", "封面设计"], ["节庆插画", "复杂自然景观"], "同心圆过密会变成靶心，应让黑洞和手部关系保持清晰。", "捧持黑洞与同心圆", "拥抱虚无与隐藏自我", "黑色石球", "无字相框", "空白展厅", ["灰黑白", "圆形中心"]),
R("Aix0124", "巨面切柱", "graphic", "巨大蓝紫面孔被黑色建筑柱切成碎片，顶部微小人物站在其上，橙色天空与极端尺度制造被观察的压迫。", ["巨型面孔", "黑色切柱", "蓝紫", "橙光", "尺度反差"], ["巨面切柱", "fragmented giant face", "watching monolith"], "以蓝紫巨面、黑色垂直切柱和橙色天空表现巨物观察者与微小个体。", "硬边矢量色块结合漫画式线条，建筑柱保持纯黑剪影。", "蓝紫冷色面孔对橙米暖天空，黑柱作为强骨架。", "垂直切割与顶部微小人物构成巨物/小人的极端尺度关系。", "平面光配局部柔和渐变，避免写实皮肤和建筑反光。", "低密度印刷噪点与干净色面并存。", ["真实五官特写", "均匀小物件铺满画面", "乱码文字与伪文字"], ["概念海报", "奇幻封面", "社会寓言"], ["温馨生活图", "产品目录"], "切柱太多会让巨面不可辨认，应保留一个主眼或主轮廓作为视觉锚点。", "巨面与垂直黑柱", "微小自我与巨大观察者", "黑色纪念碑", "观景塔", "橙色荒原", ["蓝紫巨物", "黑柱切割"]),
R("Aix0125", "水箱思域", "illustration", "透明水箱取代人物头部，气泡在蓝色空间中缓慢上升，清新的平滑笔触把思想困在一座可见容器里。", ["透明水箱", "气泡", "蓝色空间", "清新超现实", "容器头部"], ["水箱思域", "aquarium mind", "glass head"], "以透明水箱头部、气泡和清新蓝色空间表现被困思想的超现实插画。", "平滑数字绘画与简化人物结合，透明边缘清澈而不写实炫光。", "蓝色水体与白色衣物形成清冷低饱和关系。", "透明容器置于人物肩颈上方，内部气泡提供向上的节奏。", "均匀柔光，玻璃只用少量边缘高光说明透明关系。", "水面微波、气泡和干净渐变，避免复杂纹理。", ["玻璃摄影级反射", "浑浊脏水", "乱码文字与伪文字"], ["心理插画", "环保概念", "书封"], ["动作场面", "密集城市全景"], "透明容器若没有边界会像普通蓝色头发，应保留完整几何轮廓和水位线。", "透明水箱与气泡", "身体自由与思想困住", "玻璃鱼缸", "蓝色雨靴", "安静水族馆", ["蓝色清透", "容器边界"]),
R("Aix0126", "赤室孤灯", "painting", "深红房间里的人伏在桌前创作，暖黄台灯切开压抑暗部，粗犷手绘笔触把专注变成一场深夜自救。", ["深红房间", "孤灯", "创作", "暖黄", "表现主义"], ["赤室孤灯", "red room lamp", "late night maker"], "以深红室内、单盏暖黄台灯和桌前创作姿态表现深夜专注与压抑。", "粗犷手绘数字厚涂，人物和家具用概括笔触，不追求摄影写实。", "深红背景、黑褐暗部和暖黄色光源形成强烈局部对比。", "台灯光圈集中在桌面，四周暗部包围单一动作中心。", "单一暖光源切出手和纸面，避免多色光污染。", "粗刷痕、厚薄交错和轻微颗粒保留手工感。", ["洁白商业室内", "多光源炫技", "乱码文字与伪文字"], ["创作者主题", "编辑封面", "夜间叙事"], ["户外全景", "纯产品白底图"], "红色过强会淹没创作动作，应保留桌面、手势和台灯三者关系。", "深红室内与孤灯", "专注动作与压抑环境", "钢笔", "旧台灯", "深夜工作室", ["深红底色", "单一暖光"]),
R("Aix0127", "墨升彩涡", "graphic", "黑色墨滴从人物头顶升向彩色漩涡，蓝绿背景衬托红黄蓝终点，把沉重混乱拉成一条有方向的精神通道。", ["黑色墨升", "彩色漩涡", "蓝绿", "垂直通道", "精神转化"], ["墨升彩涡", "ink to color", "ascending vortex"], "以黑色上升墨形、顶部彩色漩涡和蓝绿底色表现混乱通向秩序。", "平面数字插画，墨形硬边与彩涡圆形层次形成媒介对照。", "蓝绿冷底配红黄蓝小范围彩色终点，黑色贯穿两者。", "从下向上收束的垂直路径，把暗部引到顶部旋涡。", "平面光，彩色终点承担焦点而不做真实发光。", "墨滴边缘略粗糙，色块保持干净并带轻微颗粒。", ["无限彩虹渐变", "写实烟雾摄影", "乱码文字与伪文字"], ["转化主题", "音乐视觉", "概念海报"], ["日常写实", "信息图表"], "黑色上升物若被背景吞没会失去路径，应保证轮廓和顶部终点有明度差。", "墨滴通向彩色漩涡", "沉重混乱与精神转化", "墨水瓶", "彩色陀螺", "蓝绿色实验室", ["黑色上升路径", "红黄蓝终点"]),
R("Aix0128", "百面阶梯", "illustration", "人物站在楼梯中央，漂浮的人脸像社会回声包围四周，蓝黑白漫画线条把孤独个体推入无数凝视。", ["漂浮人脸", "楼梯", "社会凝视", "蓝黑白", "漫画线条"], ["百面阶梯", "staircase of faces", "crowd gaze"], "以蓝黑白楼梯、重复漂浮面孔和孤立人物表现社会压力与个体迷失。", "清晰漫画线条结合平涂块面，重复面孔只需概括表情结构。", "冷蓝背景、黑衣和白脸形成有限三色关系。", "楼梯提供纵深，重复面孔围成包围式节奏，主体保持单一焦点。", "均匀冷光，不用戏剧性写实阴影破坏漫画平面。", "纸面颗粒、线稿抖动和少量套印偏移。", ["每张脸都写实细描", "欢快糖果色", "乱码文字与伪文字"], ["社会寓言", "心理封面", "漫画概念"], ["产品静物", "自然风景摄影"], "重复脸过多会变成杂乱纹理，应设置清晰层级和一条可读楼梯路径。", "楼梯与重复面孔", "孤立个体与群体凝视", "旧相框", "楼梯扶手", "无出口楼梯间", ["蓝黑白", "重复面孔节奏"]),
R("Aix0129", "黑玫绷带", "painting", "黑玫瑰丛中的人物以白色绷带包裹头部，蝴蝶在暗色花影间飞出，死亡与治愈以细腻哥特笔触相遇。", ["黑玫瑰", "白绷带", "蝴蝶", "哥特", "死亡与治愈"], ["黑玫绷带", "black rose bandage", "gothic healing"], "以黑玫瑰、白色包扎和蝴蝶飞舞表现受损、治愈与死亡之美。", "细腻数字厚涂，花瓣、布带和翅膀边缘柔和但主体层次清楚。", "黑色与白色构成主关系，只用极少冷灰或暗红调节。", "人物被花丛包围，白色布带和蝴蝶形成向外的轻盈动势。", "暗背景中以柔和侧光托出白布与翅膀，不使用强烈舞台光。", "丝绒暗面、花瓣细节和轻微胶片颗粒。", ["鲜艳花园色", "血腥伤口细节", "乱码文字与伪文字"], ["暗黑浪漫", "书封", "叙事肖像"], ["快节奏运动", "明亮儿童图"], "花丛过密会遮住包扎结构，应保留一条白色视觉流向和少量蝴蝶焦点。", "黑玫瑰与白色包扎", "死亡象征与生命飞出", "黑色花瓶", "白色缎带", "暗色温室", ["黑白主调", "蝴蝶轻盈动势"]),
R("Aix0130", "裂天静坐", "graphic", "盘腿人物头顶被一道裂缝和闪电刺穿天空，米色留白与蓝黑平涂把禅定的稳定和觉醒的暴烈放在同一条轴上。", ["天空裂缝", "静坐", "米色留白", "闪电", "极简"], ["裂天静坐", "split sky meditation", "quiet rupture"], "以盘腿姿态、天空裂缝和米色留白表现静定与突然觉醒的极简海报。", "极简矢量线条与平面填色，裂缝边缘锐利而人物姿态稳定。", "米色背景、深蓝黑人物和少量冷蓝裂光形成克制配色。", "中心垂直轴从静坐身体延伸到天空裂口，留白承担呼吸。", "几乎无光影，仅以裂缝的明暗和线条表达冲击。", "平滑纸面与少量细颗粒，不加入写实云层。", ["复杂风景细节", "强烈爆炸特效", "乱码文字与伪文字"], ["冥想海报", "精神主题", "编辑封面"], ["群像叙事", "写实室内"], "裂缝过宽会把画面切断，应保持细长方向和人物中心轴的连续。", "头顶天空裂缝", "静定与暴烈觉醒", "陶碗", "裂纹石板", "米色空旷庭院", ["米色留白", "细长裂缝"]),
R("Aix0131", "屏焰头盒", "graphic", "发光屏幕替代人物头部，后方白黄火焰与红衣形成冷机器和热烈燃烧的赛博寓言，高饱和色块带有波普冲击。", ["屏幕头部", "火焰", "赛博波普", "高饱和", "机器与热"], ["屏焰头盒", "screen head fire", "cyber pop burn"], "以发光屏幕头部、红蓝高饱和色块和背后火焰表现信息过载与头脑燃烧。", "波普式硬边数字插画，屏幕和火焰用概括几何形而非写实材质。", "冷蓝背景对红衣与白黄火焰，形成三组高饱和焦点。", "方形屏幕的稳定几何与火焰向上动势形成冷暖结构冲突。", "屏幕自发亮但不使用复杂反射，火焰以色块表达热度。", "干净色面加轻微印刷颗粒，避免金属塑料质感。", ["真实电子产品广告", "烟雾遮满主体", "乱码文字与伪文字"], ["科技概念", "专辑封面", "未来寓言"], ["古典静物", "柔和婚礼主题"], "屏幕内部若出现伪文字会污染风格，应保持抽象光面或无字图形。", "屏幕头部与火焰", "冷机器与热烈燃烧", "旧电视", "发光盒子", "蓝色工业走廊", ["蓝红黄高饱和", "方屏与火焰"]),
R("Aix0132", "红蓝困室", "painting", "红色房间里的瘫坐人物被蓝色窗光切开，粗犷表现主义笔触让安静室内充满焦虑和躁动。", ["红色室内", "蓝色阴影", "瘫坐", "表现主义", "焦虑"], ["红蓝困室", "red blue room", "expressionist stillness"], "以红蓝强对比室内、瘫坐姿态和粗犷笔触表现压抑中的焦虑。", "表现主义数字厚涂，形体略扭曲但动作和空间关系可读。", "红色主调与蓝色窗口阴影互相挤压，黑色作为结构线。", "低矮坐姿被墙面和窗框包围，形成封闭矩形空间。", "窗外冷光与室内红光对撞，避免多余光源。", "粗刷痕、干裂边缘和厚重颗粒增强心理重量。", ["平滑商业插画", "明亮欢快色彩", "乱码文字与伪文字"], ["心理叙事", "电影感封面", "表现主义海报"], ["轻盈儿童题材", "纯白产品图"], "红蓝面积失衡会变成普通房间，应让两种光色都参与叙事并保留坐姿。", "红室与蓝窗光", "瘫坐身体与躁动环境", "单人椅", "窗帘", "狭小出租屋", ["红蓝冲突", "封闭室内"]),
R("Aix0133", "像素散首", "graphic", "人物头部向上分解成黑白方块和像素碎片，蓝色背景与几何硬边把记忆消散转成数字化身。", ["像素碎片", "方块解体", "蓝白黑", "数字消散", "硬边几何"], ["像素散首", "pixel dissolve", "fragmented memory"], "以方块化头部、蓝白黑配色和向上飘散的像素表现数字化消散。", "硬边几何平涂，像素块大小有节奏而非随机噪点。", "冷蓝背景、白色留光和黑色衣物构成克制三色关系。", "实体人物向上分解，方块路径从密到疏，形成明确消散方向。", "均匀平光，靠色块边界和密度变化建立层次。", "干净数字表面，局部加入低强度屏幕颗粒。", ["液体写实变形", "复杂摄影背景", "乱码文字与伪文字"], ["数字艺术", "科技封面", "记忆主题"], ["古典肖像", "自然写生"], "像素碎片若遍布全身会失去解体重点，应把密度集中在头部上方。", "方块头部向上解体", "实体身体与数字消散", "像素收音机", "方形积木", "空白蓝色机房", ["蓝白黑", "由密到疏的方块"]),
R("Aix0134", "水下梦首", "painting", "人物身体留在水面之上，头部沉入波纹与蓝色梦境，平滑水彩线条把沉浸和窒息写成静谧超现实。", ["水下头部", "水波", "蓝色梦境", "水彩", "沉浸"], ["水下梦首", "underwater dream", "submerged thought"], "以水下头部、水波线条和蓝白色调表现沉浸、梦境与轻微窒息感。", "水彩感数字绘画，流线柔软，人物与水面边界清楚。", "蓝色和白色为主，加入极少灰青建立水下深度。", "水平水面切过人物头部，波纹向四周扩散形成静态节奏。", "柔和顶光穿过水面，不使用强烈水下电影光。", "半透明水纹、细颗粒和纸面晕染。", ["浑浊恐怖水底", "装饰性可读文字", "乱码文字与伪文字"], ["梦境封面", "诗意插画", "心理主题"], ["硬朗机械图", "热闹群像"], "水面边界模糊会让主体消失，应保留清楚的水平切线和头部位置。", "水面切过头部", "陆地身体与水下意识", "玻璃水盆", "白色浮标", "安静室内水池", ["蓝白水波", "水平切线"]),
R("Aix0135", "多眼暗影", "illustration", "角落里的小人物被巨大多眼阴影覆盖，紫蓝空间与黄色眼点把童年恐惧、监视和无力感压成扁平寓言。", ["多眼阴影", "紫蓝", "黄眼", "巨物压迫", "扁平寓言"], ["多眼暗影", "many-eyed shadow", "watching monster"], "以紫蓝暗空间、巨大多眼阴影和微小人物表现被监视的内心恐惧。", "扁平数字插画，阴影轮廓大而简洁，眼点保持图形化。", "紫蓝地面与黑色巨影为主，黄色眼点作为有限焦点。", "小人物置于角落，巨影占据背景并形成包围弧线。", "低照度平光，黄色眼点只做图形亮点，不做写实发光。", "干净色块、轻微纸张噪点和少量边缘粗糙。", ["可爱怪物表情", "眼睛数量过度写实", "乱码文字与伪文字"], ["心理海报", "奇幻封面", "儿童阴影寓言"], ["明快产品广告", "写实建筑"], "眼点过多会变成装饰纹理，应保留少量不同大小的凝视点和清楚的小人比例。", "巨型多眼阴影", "微小个体与被监视恐惧", "黄色夜灯", "黑色毛毯", "紫蓝角落房间", ["紫蓝黑底", "少量黄眼焦点"]),
R("Aix0136", "万手思潮", "illustration", "人物侧影被无数半透明手臂从头部向左上放射，黄蓝渐变和颗粒印刷把外在冷静与思绪泛滥同时具象化。", ["放射手臂", "黄蓝互补", "心理压力", "半透明", "颗粒印刷"], ["万手思潮", "hands of thought", "radiant anxiety"], "以侧影人物、放射状半透明手臂和黄蓝渐变表现思绪泛滥与内在压力。", "硬边人物与软边幽灵手臂并置，保持现代社论插画的概括度。", "亮黄至蓝紫的渐变与深蓝人物形成强互补关系。", "主体位于下方，手臂沿对角线向左上扩散，形成放射动势。", "背景使用平滑渐变，手臂以半透明叠层表达非实体感。", "旧印刷颗粒、衣物粗糙面和柔化手臂边缘。", ["写实断肢效果", "均匀彩虹背景", "乱码文字与伪文字"], ["心理海报", "社论插画", "创意封面"], ["温馨生活照", "复杂产品说明"], "手臂数量过多会失去节奏，应保持几条主方向和明确的主体轮廓。", "放射状半透明手臂", "外在冷静与内在泛滥", "手套", "树枝", "黄蓝渐变空房", ["黄蓝渐变", "左上放射"]),
R("Aix0137", "记忆光束", "graphic", "人物站在青色垂直光束中，照片卡片般的碎片悬浮四周，深黑蓝空间把回忆变成一场无声审讯。", ["垂直光束", "记忆碎片", "青色", "悬浮卡片", "悬疑"], ["记忆光束", "memory beam", "floating evidence"], "以青色垂直光束、悬浮记忆碎片和黑蓝空间表现回忆与审讯感。", "概念海报式硬边图形，漂浮物简化为无文字的照片形块。", "黑蓝暗底配青色光柱和白灰碎片，色彩克制。", "人物位于光束中心，碎片围绕形成纵向证据场。", "单一体积光束配柔和光晕，避免多色霓虹。", "轻颗粒、半透明边缘和少量纸片阴影。", ["可读照片文字", "杂乱拼贴排版", "乱码文字与伪文字"], ["悬疑封面", "记忆主题", "概念海报"], ["欢快广告", "写实群像"], "悬浮碎片过大或过多会遮住人物，应保留中心光柱的连续空间。", "青色光束与悬浮碎片", "记忆展示与无声审讯", "空白相片", "透明卡片", "黑色档案室", ["青色光柱", "无字碎片"]),
R("Aix0138", "绿线窥窗", "graphic", "窗边人物被一道亮绿色对角线切开，漫画硬边与黑色空间将窥视和孤独压缩成一格安静分镜。", ["绿色斜光", "窗边", "漫画分镜", "黑色空间", "窥视"], ["绿线窥窗", "green diagonal light", "window watcher"], "以亮绿色对角光束、窗边孤独人物和黑色空间表现窥视感。", "漫画式硬边线条与平涂色块，构图像一格被截取的电影分镜。", "黑色背景、亮绿光线和少量红褐服色形成三点配色。", "对角光束切开矩形窗景，人物被放在光与暗的边界。", "单一斜向光源，亮部锐利，不加入复杂摄影光晕。", "细线稿、轻颗粒和局部纸张纹理。", ["大量对白文字", "柔焦浪漫摄影", "乱码文字与伪文字"], ["漫画封面", "都市叙事", "悬疑海报"], ["自然全景", "多主体群像"], "对角线不够强会失去分镜张力，应让绿色光带成为唯一明确方向。", "绿色对角光束", "窥视与孤独", "百叶窗", "绿玻璃", "夜间窗边", ["黑绿对比", "强对角线"]),
R("Aix0139", "抗光长影", "graphic", "人物举手遮住强光，背后放射出巨大长影，黄底黑剪影与紫色衣物把抗拒真相变成强烈平面符号。", ["强背光", "放射长影", "黄黑紫", "剪影", "抗拒真相"], ["抗光长影", "resisting light", "radiant shadow"], "以强烈黄底、黑色剪影和放射长影表现个体抗拒光明与真相。", "硬边剪影与几何放射线条，整体保持海报式平面。", "亮黄背景、纯黑主体和少量紫色形成有限高对比。", "手势位于光源前方，长影向四周放射并构成中心压力。", "背光均匀而直接，影子采用图形化边缘而非真实投影。", "平滑色面配极轻印刷颗粒。", ["写实太阳光晕", "复杂背景物件", "乱码文字与伪文字"], ["社会海报", "概念封面", "动作寓言"], ["柔和肖像", "产品静物"], "放射线过密会淹没手势，应保留一个清楚的遮光动作和少量主影线。", "举手与放射长影", "个体抗拒光明", "手电筒", "遮光板", "空旷黄色广场", ["黄黑主调", "放射长影"]),
R("Aix0140", "橙缝门影", "graphic", "深蓝门口的少年被百叶窗般的橙色条纹光切过脸部，扁平矢量把童年秘密藏在门后。", ["条纹光", "深蓝橙色", "门口", "扁平矢量", "秘密"], ["橙缝门影", "orange shutter light", "door secret"], "以深蓝门口、橙色条纹光和被遮面部表现门后的秘密与童年压抑。", "清晰矢量平涂，条纹光保持等距节奏，轮廓干净。", "深蓝冷底与橙色暖光形成单一冷暖互补。", "门框形成框中框，条纹光横向切过人物，制造遮蔽层。", "条纹光是唯一主光源，亮暗切割平整而不写实。", "平滑色面和轻微纸张颗粒。", ["复杂室内陈设", "多色霓虹", "乱码文字与伪文字"], ["成长主题", "电影海报", "悬疑封面"], ["群像庆典", "自然风景"], "条纹过密会把脸完全抹掉，应保留眼鼻或轮廓中的一处识别点。", "门缝与条纹光", "童年外表与门后秘密", "旧门锁", "折叠百叶", "深蓝走廊", ["深蓝橙光", "框中框"]),
